hybrid-quantum-classical-algorithm.pseudocode:
def vqe(ansatz, hamiltonian, optimizer, theta, n_iter):
    # ansatz: 매개변수 양자회로, optimizer: 고전 최적화
    for _ in range(n_iter):
        def cost(t):
            state = ansatz.run(t)  # 양자 회로 실행
            return measure_expectation(state, hamiltonian)
        energy = cost(theta)
        # 고전 옵티마이저가 파라미터 갱신 (기울기·무기울기)
        theta = optimizer.step(cost, theta)
    return theta, energy  # 근사 바닥상태 에너지

hybrid-search.pseudocode:
def reciprocal_rank_fusion(rankings, k=60):
    # rankings: 각 검색기의 순위 리스트 [문서ID...]
    scores = {}
    for ranking in rankings:
        for rank, doc in enumerate(ranking):
            # 순위가 높을수록(작을수록) 큰 점수
            prev = scores.get(doc, 0)
            scores[doc] = prev + 1 / (k + rank)
    return sorted(scores, key=scores.get, reverse=True)

hypercube-topology.pseudocode:
def ecube_route(src, dst, n):
    # n차원 하이퍼큐브: 낮은 비트부터 다른 비트 교정
    path, cur = [src], src
    for i in range(n):
        if (cur ^ dst) >> i & 1:  # i번째 비트가 다르면
            cur ^= 1 << i  # 차원 i 링크로 이동
            path.append(cur)
    return path  # 홉 수 = 해밍 거리 ≤ n(지름)

hyperparameter-optimization.pseudocode:
# 랜덤 탐색 + K-겹 교차검증 (블랙박스 최적화)
def random_search(space, n_trials, data, k=5):
    best, best_score = None, float('-inf')
    for _ in range(n_trials):
        # 각 하이퍼파라미터를 분포에서 무작위 샘플
        lam = {name: sample(dist)
               for name, dist in space.items()}
        score = cross_val_score(lam, data, k)  # 목적함수
        if score > best_score:
            best, best_score = lam, score
    return best, best_score

